sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        // Hide both fields by default when form loads
        g_form.setDisplay('email', false);
        g_form.setDisplay('mobile_number', false);
        g_form.clearValue('email');
        g_form.clearValue('mobile_number');
        return;
    }

    // Hide both fields first
    g_form.setDisplay('email', false);
    g_form.setDisplay('mobile_number', false);
    g_form.clearValue('email');
    g_form.clearValue('mobile_number');

    // Show appropriate field based on contact_type selection
    if (newValue === 'email') {
        g_form.setDisplay('email', true);
        g_form.showFieldMsg('email', '', 'info'); // Clear any existing messages
    } else if (newValue === 'mobile') {
        g_form.setDisplay('mobile_number', true);
        g_form.showFieldMsg('mobile_number', '', 'info'); // Clear any existing messages
    }
}
